const b = $input.first().json.body || {};
    const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    const mail = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
    return [{ json: {
      project_id: uuid.test(b.project_id || '') ? b.project_id : 'a0000001-0000-0000-0000-000000000001',
      feature_description: String(b.feature_description || '').trim().slice(0, 1000),
      notify_email: mail.test(b.notify_email || '') ? b.notify_email : 'htchannelas@gmail.com',
    } }];

const inp = $('Prepare Input').first().json;
    const ctx = $input.first().json;
    const existing = Array.isArray(ctx.existing_titles) ? ctx.existing_titles : [];
    const prompt = [
      'Bạn là một AI Project Manager chuyên nghiệp.',
      'Dự án: ' + (ctx.name || '(không rõ)') + ' - ' + (ctx.description || ''),
      'Deadline dự án: ' + (ctx.deadline || 'chưa có'),
      'Các task ĐÃ CÓ (không được tạo trùng): ' + (existing.length ? existing.join('; ') : 'chưa có'),
      '',
      'Yêu cầu tính năng mới: "' + inp.feature_description + '"',
      '',
      'Hãy chia nhỏ tính năng thành 3 đến 5 task kỹ thuật cụ thể.',
      'CHỈ trả về một JSON Array thuần (không markdown, không giải thích) theo cấu trúc:',
      '[{"title":"...","description":"...","story_points":3,"required_skills":["Next.js","PostgreSQL"],"priority":"HIGH"}]',
      'story_points từ 1-8; priority là một trong LOW, MEDIUM, HIGH, URGENT.',
    ].join('\n');
    return [{ json: { prompt } }];

try {
      let raw = $input.first().json.content.parts[0].text || '';
      raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
      const s = raw.indexOf('['), e = raw.lastIndexOf(']');
      if (s < 0 || e < 0) throw new Error('Không tìm thấy JSON array trong phản hồi AI');
      const tasks = JSON.parse(raw.slice(s, e + 1));
      if (!Array.isArray(tasks) || tasks.length === 0) throw new Error('AI trả về mảng task rỗng');
      return [{ json: { ok: true, tasks } }];
    } catch (err) {
      return [{ json: { ok: false, error: 'Lỗi xử lý phản hồi AI: ' + err.message } }];
    }

const inp = $('Prepare Input').first().json;
    const ctx = $('Get Project Context').first().json;
    const existing = Array.isArray(ctx.existing_titles) ? ctx.existing_titles : [];
    const seen = new Set(existing.map((t) => String(t).toLowerCase().trim()));
    const okPr = ['LOW', 'MEDIUM', 'HIGH', 'URGENT'];
    const q = (s) => "'" + String(s ?? '').replace(/'/g, "''") + "'";
    const tasks = [], skipped = [];
    for (const t of $input.first().json.tasks) {
      const title = String(t.title || '').trim().slice(0, 255);
      if (!title) continue;
      if (seen.has(title.toLowerCase())) { skipped.push(title); continue; }
      seen.add(title.toLowerCase());
      const pr = String(t.priority || '').toUpperCase();
      tasks.push({
        title,
        description: String(t.description || ''),
        story_points: Math.min(8, Math.max(1, parseInt(t.story_points) || 3)),
        priority: okPr.includes(pr) ? pr : 'MEDIUM',
        required_skills: Array.isArray(t.required_skills) ? t.required_skills.map(String) : [],
      });
    }
    const values = tasks.map((t) => '(' + [
      q(inp.project_id) + '::uuid', q(t.title), q(t.description), t.story_points,
      'ARRAY[' + t.required_skills.map(q).join(',') + ']::text[]', q(t.priority), "'TODO'",
    ].join(',') + ')');
    const sql = tasks.length
      ? 'INSERT INTO tasks (project_id,title,description,story_points,required_skills,priority,status) VALUES ' +
        values.join(',') + ' RETURNING id,title,story_points,priority'
      : 'SELECT NULL::uuid AS id WHERE false';
    return [{ json: { sql, skipped, generated: tasks.length } }];

const rows = $input.all().map((i) => i.json).filter((r) => r.id);
    const q = (s) => "'" + String(s ?? '').replace(/'/g, "''") + "'";
    const sql = rows.length
      ? 'INSERT INTO activity_history (task_id,action_type,new_value,metadata) VALUES ' +
        rows.map((r) => '(' + q(r.id) + "::uuid,'TASK_CREATED'," + q(String(r.title).slice(0, 100)) + ',' +
          q(JSON.stringify({ source: 'flow1_ai_breakdown' })) + '::jsonb)').join(',')
      : 'SELECT 1';
    return [{ json: { sql, created: rows } }];

const created = $('Build Log SQL').first().json.created;
    const norm = $('Normalize and Dedupe').first().json;
    const inp = $('Prepare Input').first().json;
    const esc = (s) => String(s).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
    const rows = created.map((t) => '<tr><td>' + esc(t.title) + '</td><td>' + t.story_points + '</td><td>' + t.priority + '</td></tr>').join('');
    const html = '<h2>🤖 AI Task Breakdown hoàn tất</h2><p><b>Yêu cầu:</b> ' + esc(inp.feature_description) + '</p>' +
      '<p>Đã tạo <b>' + created.length + '</b> task, bỏ qua <b>' + norm.skipped.length + '</b> task trùng.</p>' +
      '<table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Task</th><th>SP</th><th>Ưu tiên</th></tr>' + rows + '</table>';
    return [{ json: {
      notify_email: inp.notify_email,
      subject: '✅ [Luồng 1] AI đã tạo ' + created.length + ' task mới',
      html,
      response: { success: true, created_count: created.length, skipped: norm.skipped, tasks: created },
    } }];
